{"hypotheses": [
  {
    "name": "Organizational Capital and Industry Concentration Shock",
    "mechanism": "Firms with high organizational capital (OrgCap) benefit from industry-level concentration disruptions (HerfAsset), as their managerial flexibility allows them to capitalize on market structure shifts. By combining these, we expect a premium from firms best positioned to exploit transient competitive changes, beyond the sum of the components.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "HerfAsset"},
        {"weight": -0.5, "primitive": "Industry Momentum"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Brand Investment with Forecast Dispersion Hedge",
    "mechanism": "Firms with strong brand capital investment (BrandInvest) and low analyst forecast dispersion (ForecastDispersion) are likely to have sustainable cash flows and fewer information asymmetries. Hedging out high dispersion emphasizes those with the clearest growth prospects and hidden competitive advantages.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": -0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "ForecastDispersion", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Earnings Surprise Efficiency",
    "mechanism": "Earnings surprise (EarningsSurprise) predicts returns, but its efficacy rises when combined with firms showing strong price delay (PriceDelayTstat), suggesting markets inefficiently incorporate timely news in these stocks. The combination identifies inefficiency pockets.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": 0.5, "primitive": "PriceDelayTstat"},
        {"weight": -0.5, "primitive": "BidAskSpread"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Deferred Revenue with Operating Leverage Tilt",
    "mechanism": "Firms accumulating deferred revenue (DelDRC) while maintaining high operating leverage (OPLeverage) are better able to buffer shocks and reinvest for growth, especially during low rate environments. The mix targets structural growth with cash flow flexibility.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DelDRC"},
        {"weight": 0.5, "primitive": "OPLeverage"},
        {"weight": -0.5, "primitive": "BookLeverage"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "DelDRC", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Supply Chain Resilience and Asset Turnover",
    "mechanism": "Firms benefiting from positive supplier momentum (iomom_supp) and accelerating asset turnover (ChAssetTurnover), but with tempered employment growth (hire), are likely to be improving efficiency and adapting supply chains without overextending resources.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_supp"},
        {"weight": 0.5, "primitive": "ChAssetTurnover"},
        {"weight": -0.5, "primitive": "hire"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "iomom_supp", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.68,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "R&D Surprises with Analyst Optimism Control",
    "mechanism": "Unexpected R&D increases (SurpriseRD) typically reward firms investing in innovation, but controlling for analyst optimism (AOP) distinguishes true innovation from mere positive sentiment, isolating genuine discovery from hype-driven moves.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "SurpriseRD"},
        {"weight": -0.5, "primitive": "AOP"},
        {"weight": 0.5, "primitive": "PatentsRD"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.66,
    "expected_decay_half_life_months": 28
  },
  {
    "name": "Real Estate Asset Play in Volatile Regimes",
    "mechanism": "Firms with substantial real estate holdings (realestate) but low market leverage (Leverage) and muted volume volatility (VolSD) are underappreciated as safe asset plays during periods of elevated market volatility, creating a unique defensive composite.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "realestate"},
        {"weight": -0.5, "primitive": "Leverage"},
        {"weight": -0.5, "primitive": "VolSD"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "realestate", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.58,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Pension Funding and Net Debt Hedged",
    "mechanism": "Firms with healthy pension funding (FR) but hedged for excessive net debt (NetDebtFinance) and sudden debt issuance (DebtIssuance) avoid underfunded liabilities and balance sheet risk, especially when rates rise, creating a durable hybrid safety premium.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "FR"},
        {"weight": -0.5, "primitive": "NetDebtFinance"},
        {"weight": -0.5, "primitive": "DebtIssuance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 40
  }
]}
